/// Calls crab:full/telemetry@0.1.0#report on the workload named
/// `workload` through the host mesh (crabcraft.call). The Err covers
/// transport failures, remote status-1 failures, AND the WIT result
/// err case.
pub fn telemetry_report(workload: &str, s: Sample) -> Result<(), String> {
    let mut params = Vec::new();
    crab_sdk::codec::encode(&Value::try_from(s)?, &mut params);
    let reply = crab_sdk::mesh_call(workload, "crab:full/telemetry@0.1.0#report", &params)?;
    let v = crab_sdk::decode(&Type::Result {
        ok: None,
        err: Some(Box::new(Type::String)),
    }, &reply)?;
    match v {
        Value::Result(Ok(None)) => Ok(()),
        Value::Result(Ok(Some(x))) => Err(format!("unexpected result payload {x:?}")),
        Value::Result(Err(Some(x))) => Err(String::try_from(*x)?),
        Value::Result(Err(None)) => Err("missing err payload".to_string()),
        other => Err(format!("expected result, got {other:?}")),
    }
}

